SELECT
pl.id as 'place_id',
pl.country as 'country_id',
pl.city as 'city',
pl.location as 'place_location',
pl.place as 'place',
UNIX_TIMESTAMP(pl.createdAt) as 'place_created',
UNIX_TIMESTAMP(pl.updatedAt) as 'place_last_modified',
UNIX_TIMESTAMP(pl.deletedAt) as 'deleted_at',
pl.biMapping as 'bi_mapping',
pl.address1 as 'address1',
pl.address2 as 'address2',
pl.zipcode as 'zipcode',
pl.timezone as 'timezone',
pl.timezoneOffset as 'timezone_offset',
pl.lat as 'lat',
pl.lng as 'lon',
if(pl.active = 1, true, false) as 'is_active',
pl.inspectionPointId as 'inspection_center_id',
if(json_search(pl.type, 'one', 'INSPECTION') is not null, true, false) as 'is_inspection_center',
if(json_search(pl.type, 'one', 'PURCHASE') is not null, true, false) as 'is_purchase_location',
if(json_search(pl.type, 'one', 'SELLING') is not null, true, false) as 'is_selling_location',
if(json_search(pl.type, 'one', 'CURRENT') is not null, true, false) as 'is_current_location',
if(json_search(pl.type, 'one', 'DOCUMENT') is not null, true, false) as 'is_document_location',
if(json_search(pl.type, 'one', 'PICKUP') is not null, true, false) as 'is_pickup_location',
pl.region as 'region',
pl.metaInfo as 'meta_info'
FROM fcgCar.place pl
/* where pl.updatedAt >= '{{params.start_ts}}' and pl.updatedAt < '{{params.end_ts}}' */